#include <vector>
#include <algorithm>
#include <cmath>

class Solution {
public:
    std::vector<long long> countOfPairs(int n, int x, int y) {
        if (std::abs(x - y) <= 1) {
            std::vector<long long> res(n);
            for (int i = 0; i < n; ++i) res[i] = 2LL * (n - 1 - i);
            return res;
        }
        int cycle_len = std::abs(x - y) + 1;
        int n2 = n - cycle_len + 2;
        std::vector<long long> res(n, 0);
        for (int i = 0; i < n2; ++i) res[i] = 2LL * (n2 - 1 - i);
        std::vector<long long> res2(cycle_len / 2, 2LL * cycle_len);
        if (!(cycle_len & 1)) res2.back() = cycle_len;
        res2[0] -= 2;
        for (size_t i = 0; i < res2.size(); ++i) res[i] += res2[i];
        if (x > y) std::swap(x, y);
        int tail1 = x - 1, tail2 = n - y;
        for (int tail : {tail1, tail2}) {
            if (!tail) continue;
            int i_mx = tail + (cycle_len / 2);
            long long val_mx = 4LL * std::min((cycle_len - 3) / 2, tail);
            int i_mx2 = i_mx - (1 - (cycle_len & 1));
            std::vector<long long> res3(i_mx, val_mx);
            res3[0] = 0;
            if (i_mx > 1) res3[1] = 0;
            if (!(cycle_len & 1)) res3.back() = 0;
            long long j = 4;
            int idx = 0;
            while (j < val_mx) {
                res3[idx + 2] = j;
                res3[i_mx2 - idx - 1] = j;
                j += 4;
                idx++;
            }
            for (int i = 1; i <= tail; ++i) res3[i] += 2;
            if (!(cycle_len & 1)) {
                int mn = cycle_len / 2;
                for (int i = mn; i < mn + tail; ++i) res3[i] += 2;
            }
            for (size_t i = 0; i < res3.size(); ++i) res[i] += res3[i];
        }
        return res;
    }
};

