class Solution {
    public long[] countOfPairs(int n, int x, int y) {
        if (Math.abs(x - y) <= 1) {
            long[] res = new long[n];
            for (int i = 0; i < n; ++i) res[i] = 2L * (n - 1 - i);
            return res;
        }
        int cycleLen = Math.abs(x - y) + 1;
        int n2 = n - cycleLen + 2;
        long[] res = new long[n];
        for (int i = 0; i < n2; ++i) res[i] = 2L * (n2 - 1 - i);
        long[] res2 = new long[cycleLen / 2];
        Arrays.fill(res2, 2L * cycleLen);
        if ((cycleLen & 1) == 0) res2[res2.length - 1] = cycleLen;
        res2[0] -= 2;
        for (int i = 0; i < res2.length; ++i) res[i] += res2[i];
        if (x > y) { int tmp = x; x = y; y = tmp; }
        int[] tails = { x - 1, n - y };
        for (int tail : tails) {
            if (tail == 0) continue;
            int iMx = tail + (cycleLen / 2);
            long valMx = 4L * Math.min((cycleLen - 3) / 2, tail);
            int iMx2 = iMx - (1 - (cycleLen & 1));
            long[] res3 = new long[iMx];
            Arrays.fill(res3, valMx);
            res3[0] = 0;
            if (iMx > 1) res3[1] = 0;
            if ((cycleLen & 1) == 0) res3[res3.length - 1] = 0;
            long j = 4;
            int idx = 0;
            while (j < valMx) {
                res3[idx + 2] = j;
                res3[iMx2 - idx - 1] = j;
                j += 4;
                idx++;
            }
            for (int i = 1; i <= tail; ++i) res3[i] += 2;
            if ((cycleLen & 1) == 0) {
                int mn = cycleLen / 2;
                for (int i = mn; i < mn + tail; ++i) res3[i] += 2;
